(()=>{
const MASKS = {"01_dark_lines": "data:image/png;base64,", "02_purple": "data:image/png;base64,", "03_teal": "data:image/png;base64,", "04_gold_yellow": "data:image/png;base64,", "05_orange_red": "data:image/png;base64,", "06_skin_tan": "data:image/png;base64,", "07_silver_white": "data:image/png;base64,"};
const specs=[
 ['01_dark_lines',205,1.00],['02_purple',285,1.13],['03_teal',165,.91],
 ['04_gold_yellow',48,1.27],['05_orange_red',8,1.06],['06_skin_tan',32,.78],['07_silver_white',210,.64]
];
const cards=[...document.querySelectorAll('.card')];

cards.forEach(card=>{
 const base=new Image(); base.src='./mira-jii.jpg'; base.className='layer base'; card.append(base);
 specs.forEach(([n])=>{const im=new Image();im.src=MASKS[n];im.className='layer holo';im.dataset.mask=n;card.append(im)});
});

const menu=document.querySelector('#menu');
const viewer=document.querySelector('#viewer');
const pair=document.querySelector('#pair');
const status=document.querySelector('#status');
let active=false,bB=null,bG=null,drag=false;

const show=v=>{menu.classList.toggle('active',!v);viewer.classList.toggle('active',v)};
document.querySelector('#openMira').onclick=()=>show(true);
document.querySelector('#back').onclick=()=>show(false);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));

function paint(t){
 t=clamp(t,-1,1);
 cards.forEach(card=>specs.forEach(([n,base,rate])=>{
   const hue=(base+t*150*rate+360)%360;
   const el=card.querySelector(`[data-mask="${n}"]`);
   if(n==='07_silver_white'){
     el.style.filter=`brightness(1.22) sepia(.28) saturate(2.6) hue-rotate(${hue}deg)`;
   }else{
     el.style.filter=`brightness(.86) sepia(1) saturate(8.5) hue-rotate(${hue}deg) brightness(1.16)`;
   }
 }));
}
function orient(e){
 if(!active)return;
 if(bB===null){bB=e.beta||0;bG=e.gamma||0}
 let x=((e.gamma||0)-bG)/25,y=((e.beta||0)-bB)/40;
 if(matchMedia('(orientation:portrait)').matches){let q=x;x=y;y=-q}
 paint(x+y*.22);
}
document.querySelector('#start').onclick=async()=>{
 try{
  if(typeof DeviceOrientationEvent==='undefined'){status.textContent='センサー非対応 / ドラッグ操作可';return}
  if(typeof DeviceOrientationEvent.requestPermission==='function'&&await DeviceOrientationEvent.requestPermission()!=='granted'){
    status.textContent='センサー許可なし / ドラッグ操作可';return
  }
  bB=bG=null;active=true;
  addEventListener('deviceorientation',orient,true);
  document.querySelector('#start').textContent='TILT ACTIVE';
  status.textContent='現在角度を基準に設定';
 }catch(e){status.textContent='センサーを開始できません'}
};
document.querySelector('#reset').onclick=()=>{bB=bG=null;paint(0)};
function pointer(e){
 const r=pair.getBoundingClientRect();
 paint(((e.clientX-r.left)/r.width-.5)*2);
}
pair.onpointerdown=e=>{drag=true;pair.setPointerCapture(e.pointerId);pointer(e)};
pair.onpointermove=e=>{if(drag)pointer(e)};
pair.onpointerup=pair.onpointercancel=()=>drag=false;

paint(0);
if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
})();